def solve(inputs: dict) -> float:
    remainders = inputs.get('remainders', [234, 652, 906, 355])
    moduli = inputs.get('moduli', [269, 881, 1039, 2311])

    # Extended Euclidean Algorithm to find modular inverse
    def extended_gcd(a, b):
        if a == 0:
            return b, 0, 1
        gcd, x1, y1 = extended_gcd(b % a, a)
        x = y1 - (b // a) * x1
        y = x1
        return gcd, x, y

    def mod_inverse(a, m):
        gcd, x, _ = extended_gcd(a % m, m)
        if gcd != 1:
            return None
        return (x % m + m) % m

    # Chinese Remainder Theorem
    M = 1
    for m in moduli:
        M *= m

    x = 0
    for i in range(len(remainders)):
        Mi = M // moduli[i]
        yi = mod_inverse(Mi, moduli[i])
        x += remainders[i] * Mi * yi

    x = x % M
    return float(x)
